static p::Matrix matrix(NSArray* a){if(a.count!=9)throw std::runtime_error("bad matrix");p::Matrix v{};for(unsigned i=0;i<9;++i)v[i]=[a[i] doubleValue];return v;}
static double norm(const p::Matrix& a){double n=0;for(double v:a)n=std::max(n,std::abs(v));return n;}
static double error(const p::Matrix& a,const p::Matrix& b){double n=0;for(unsigned i=0;i<9;++i)n=std::max(n,std::abs(a[i]-b[i]));return n;}
static double f32bits(NSString* value){std::uint32_t u=static_cast<std::uint32_t>(std::stoul([value UTF8String],nullptr,16));float f;std::memcpy(&f,&u,4);if(!std::isfinite(f))throw std::runtime_error("bad parameter");return f;}
static p::Parameters parameters(NSDictionary* world,p::MaterialKind kind){std::array<double,20>a{};NSArray* values=world[@"source_parameters"];if(values.count!=20)throw std::runtime_error("parameter count");for(unsigned i=0;i<20;++i)a[i]=f32bits(values[i][@"compiled_f32_bits"]);auto q=p::parameters(kind);q.density=a[0];for(unsigned i=0;i<6;++i)q.c[i]=a[1+i]/1e6;for(unsigned i=0;i<3;++i)q.shear[i]=a[7+i]/1e6;q.sigmaReference=a[10]/1e6;for(unsigned i=0;i<6;++i)q.hill[i]=a[11+i];q.qFloor=a[17];q.fischerBurmeisterEpsilon=a[18];return q;}
int main(int argc,char**argv){@autoreleasepool{try{if(argc!=2)throw std::runtime_error("input expected");std::ifstream input(argv[1]);if(!input)throw std::runtime_error("input missing");std::string line;p::Parameters liner{},medium{};bool header=false;unsigned count=0,fail=0;double maximum=0;std::cout<<std::setprecision(17);
while(std::getline(input,line)){@autoreleasepool{NSData* data=[NSData dataWithBytes:line.data() length:line.size()];NSError* e=nil;NSDictionary* r=[NSJSONSerialization JSONObjectWithData:data options:0 error:&e];if(!r||e)throw std::runtime_error("invalid JSON");std::string record=[r[@"record"] UTF8String];if(record=="header"){for(NSDictionary* w in r[@"compiled_worlds"]){NSString* label=w[@"label"];if([label isEqualToString:@"liner_accurate_candidate"])liner=parameters(w,p::MaterialKind::liner);if([label isEqualToString:@"medium_accurate_candidate"])medium=parameters(w,p::MaterialKind::medium);}header=true;continue;}if(record!="captured_center_replay")continue;if(!header)throw std::runtime_error("header missing");const unsigned env=[r[@"environment"] unsignedIntValue],tet=[r[@"tet_id"] unsignedIntValue];NSString* material=r[@"material_name"];const auto& q=[material containsString:@"liner"]?liner:medium;auto f=matrix(r[@"F_local_high"]);const auto lo=matrix(r[@"F_local_low"]),h=matrix(r[@"F_direction_local_per_s"]);for(unsigned i=0;i<9;++i)f[i]+=lo[i];p::State old{};NSArray* olda=r[@"accepted_state"];if(olda.count!=13)throw std::runtime_error("bad state");for(unsigned i=0;i<13;++i)old[i]=[olda[i] doubleValue];auto center=s::project(q,f,old);auto tangent=s::directionalTangent(q,f,h,old,center.state);for(double& v:tangent)v*=1e6;const auto native=matrix(r[@"candidate_responses"][@"accurate_candidate"][@"tangent_local_Pa_per_s"]);double scale=norm(tangent),absolute=error(native,tangent),relative=scale>0?absolute/scale:0;maximum=std::max(maximum,relative);if(relative>1e-3)++fail;
std::cout<<"{\"environment\":"<<env<<",\"tet_id\":"<<tet<<",\"center_dl\":"<<center.state[12]-old[12]<<",\"center_yield_gap\":"<<1-center.equivalentStress<<",\"analytic_norm_Pa_per_s\":"<<scale<<",\"native_analytic_absolute_error_Pa_per_s\":"<<absolute<<",\"native_analytic_norm_relative_error\":"<<relative<<",\"zero_direction\":"<<(norm(h)==0?"true":"false")<<",\"legacy_status\":\""<<[r[@"accurate_fp64_replay"][@"status"] UTF8String]<<"\",\"samples\":[";
bool comma=false;const bool sample=norm(h)>0&&(![r[@"accurate_fp64_replay"][@"status"] isEqualToString:@"pass_resolved_components_with_nearzero_inconclusive"]||tet==0||tet==1100);
if(sample)for(double strain:{1e-4,1e-5,2e-6,1e-6,1e-7,1e-8,1e-9,1e-10}){const double step=strain/norm(h);auto plus=f,minus=f;for(unsigned i=0;i<9;++i){plus[i]+=step*h[i];minus[i]-=step*h[i];}if(comma)std::cout<<',';comma=true;try{const auto rp=s::project(q,plus,old),rm=s::project(q,minus,old);p::Matrix central{},forward{},backward{};for(unsigned i=0;i<9;++i){central[i]=(rp.firstPiola[i]-rm.firstPiola[i])*1e6/(2*step);forward[i]=(rp.firstPiola[i]-center.firstPiola[i])*1e6/step;backward[i]=(center.firstPiola[i]-rm.firstPiola[i])*1e6/step;}std::cout<<"{\"max_F_step\":"<<strain<<",\"step\":"<<step<<",\"valid\":true,\"plus_dl\":"<<rp.state[12]-old[12]<<",\"plus_gap\":"<<1-rp.equivalentStress<<",\"minus_dl\":"<<rm.state[12]-old[12]<<",\"minus_gap\":"<<1-rm.equivalentStress<<",\"central_relative\":"<<error(central,tangent)/std::max(scale,1e-300)<<",\"forward_relative\":"<<error(forward,tangent)/std::max(scale,1e-300)<<",\"backward_relative\":"<<error(backward,tangent)/std::max(scale,1e-300)<<'}';}catch(const std::exception& ex){std::cout<<"{\"max_F_step\":"<<strain<<",\"valid\":false,\"failure\":\""<<ex.what()<<"\"}";}}
std::cout<<"]}\n";++count;}}
std::cerr<<"centers="<<count<<" max_norm_relative="<<maximum<<" native_analytic_above_1e-3="<<fail<<" physical_steps=0\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}}
